<?php require 'config.php'; $pageTitle='Place an order'; $pageDescription='Send ANILLAH CLOSET an order request and confirm product availability, sizing and delivery details.'; $id=(int)($_GET['product']??0);$product=null;if($id){$s=$pdo->prepare("SELECT * FROM products WHERE id=? AND is_active=1");$s->execute([$id]);$product=$s->fetch();}$sent=false;$err=''; if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$name=trim($_POST['customer_name']??'');$phone=trim($_POST['phone']??'');$email=trim($_POST['email']??'');$pid=(int)($_POST['product_id']??0);$size=trim($_POST['size']??'');$qty=max(1,(int)($_POST['quantity']??1));$notes=trim($_POST['notes']??'');if(!$name||!$phone||!$pid){$err='Please provide your name, phone and select a product.';}else{$s=$pdo->prepare("INSERT INTO orders(customer_name,phone,email,product_id,size,quantity,notes) VALUES(?,?,?,?,?,?,?)");$s->execute([$name,$phone,$email?:null,$pid,$size,$qty,$notes]);$sent=true;}} include 'includes/header.php'; ?>
